package ai.decisionos.aside;

import android.app.*;import android.content.*;import android.graphics.Color;import android.os.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import org.json.*;import java.util.*;

/** Goal-owned native chat, visible browser and receipts. Selectable native conversation and coworker workspace compositions. */
final class GoalChatUi {
 final GoalAgentActivity a;final Handler ui=new Handler(Looper.getMainLooper());
 final String goalId,character;final GoalRules.Preset preset;LinearLayout messages;ScrollView thread;EditText input;Button send;TextView progress,address;String job="",requestId="",turnId="";boolean running=false,submitting=false,visible=true,campusTurn=false;int pollErrors=0,turnGeneration=0;JSONArray history;JSONObject pendingDocument;JSONArray steps=new JSONArray();NubiCompanionUi companion;
 boolean companionMode(){return true;}
 boolean modern(){if(companionMode())return true;return a.getPreferences(0).getBoolean("coworker_ui",true);}

 GoalChatUi(GoalAgentActivity a){this.a=a;goalId=a.gid;JSONObject g=a.store.goal(goalId);character=g.optString("character");preset=GoalRules.preset(character);history=g.optJSONArray("chatMessages");if(history==null)history=new JSONArray();}
 LinearLayout box(int color,int pad){return Ui.vertical(a,color,pad);}int dp(int n){return Ui.dp(a,n);}
 void build(){if(companion!=null)companion.dispose();companion=new NubiCompanionUi(this);companion.build();}
 void draft(String text){if(running||submitting){a.toast("지금 작업이 끝나면 새 요청을 보낼 수 있어.");return;}input.setText(text);input.setSelection(input.length());input.requestFocus();save();}
 void switchGoal(String id){if(goalId.equals(id))return;Intent i=new Intent(a,GoalAgentActivity.class).putExtra("goal_id",id);cancel();pause();a.startActivity(i);a.finish();}
 void switchAgent(String id){if(id.equals(character))return;JSONObject goal=null;for(JSONObject row:a.store.goals())if(row.optString("character").equals(id)&&!row.optString("title").startsWith("QWEN_")&&!row.optString("title").startsWith("INSTRUMENTATION")){goal=row;break;}if(goal==null){GoalRules.Preset p=GoalRules.preset(id);goal=a.store.create(id,p.title,p.topic,0);}Intent i=new Intent(a,GoalAgentActivity.class).putExtra("goal_id",goal.optString("id"));cancel();pause();a.startActivity(i);a.finish();}
 void save(){try{a.store.goal(goalId);}catch(IllegalArgumentException deleted){return;}while(history.length()>40)history.remove(0);JSONObject patch=new JSONObject();GoalStore.put(patch,"chatMessages",history);GoalStore.put(patch,"chatDraft",input==null?"":input.getText().toString());try{a.store.patchGoal(goalId,patch);}catch(IllegalArgumentException deleted){/* Goal may be removed while this activity is pausing. */}}
 JSONObject message(String role,String text){JSONObject m=new JSONObject();GoalStore.put(m,"id",UUID.randomUUID().toString());GoalStore.put(m,"role",role);GoalStore.put(m,"text",text);GoalStore.put(m,"at",System.currentTimeMillis());return m;}
 void render(){messages.removeAllViews();if(history.length()==0)bubble(message("assistant","안녕, "+preset.name+"야. 이 목표에서 뭘 도와줄까? 원하는 조건까지 말해줘."));for(int i=0;i<history.length();i++)bubble(history.optJSONObject(i));thread.post(()->thread.fullScroll(View.FOCUS_DOWN));}
 void bubble(JSONObject m){if(m==null)return;boolean user=m.optString("role").equals("user");LinearLayout row=new LinearLayout(a);row.setGravity(user?Gravity.RIGHT:Gravity.LEFT);LinearLayout b=companionMode()?new NubiCompanionUi.Bubble(a):box(user?0xffe4f0e9:modern()?Color.WHITE:0xffeeeef0,14);if(companionMode()){b.setPadding(dp(14),dp(10),dp(14),dp(10));((NubiCompanionUi.Bubble)b).setMaxWidth(dp(companion.bubbleWidthDp()));}b.setBackground(Ui.bg(user?0xffe4f0e9:companionMode()?0xfff4f4f4:modern()?Color.WHITE:0xffeeeef0,20,a));TextView t=a.txt(m.optString("text"),companionMode()?16:15,companionMode()?NubiCompanionUi.INK:GoalUi.INK,false);if(companionMode()){t.setIncludeFontPadding(false);t.setLineSpacing(0,1f);}t.setTextIsSelectable(true);b.addView(t);String state=m.optString("state");if(!state.isEmpty())b.addView(a.txt(m.has("document")&&state.equals("completed")?"문서 생성 결과 · 아래 상태 확인":stateLabel(state),11,GoalUi.MUTED,false),Ui.match(a,-2,6));
  JSONArray items=m.optJSONArray("items");if(items!=null)for(int j=0;j<items.length();j++){JSONObject item=items.optJSONObject(j);if(item==null||!GoalRules.safe(item.optString("url")))continue;LinearLayout c=box(Color.WHITE,10);c.setBackground(Ui.bg(Color.WHITE,14,a));c.addView(a.txt(item.optString("title"),14,GoalUi.INK,true));if(!item.optString("priceText").isEmpty())c.addView(a.txt(item.optString("priceText"),13,GoalUi.PURPLE,true));TextView link=a.txt(android.net.Uri.parse(item.optString("url")).getHost()+" ↗",12,GoalUi.PURPLE,false);link.setOnClickListener(v->showSource(item.optString("url")));c.addView(link);c.setOnClickListener(v->showSource(item.optString("url")));b.addView(c,Ui.match(a,-2,8));}
  JSONObject doc=m.optJSONObject("document");if(doc!=null){JSONObject manifest=doc.optJSONObject("manifest");String docState=doc.optString("state");b.addView(a.txt(docState.equals("uploaded")?"문서 업로드·원격 검증 완료":"문서 생성 · "+(docState.equals("needs_information")?"추가 정보 필요":docState.equals("draft_only")?"초안 저장":"업로드 연결 필요"),13,GoalUi.PURPLE,true));JSONArray files=manifest==null?null:manifest.optJSONArray("files");for(int n=0;files!=null&&n<files.length();n++){JSONObject file=files.optJSONObject(n);if(file==null)continue;String name=file.optString("name");if(!name.endsWith(".docx")&&!name.endsWith(".hwpx"))continue;Button open=a.button(name+" 열기",false);open.setOnClickListener(v->openDocument(doc,file));b.addView(open,Ui.match(a,-2,6));JSONObject compatible=chatGptCompatibleFile(doc,file);if(compatible!=null){Button edit=a.button("ChatGPT에 DOCX 첨부",false);edit.setOnClickListener(v->editDocumentWithChatGpt(doc,compatible));b.addView(edit,Ui.match(a,-2,4));}}}
  if(modern()&&!user&&!m.optString("state").isEmpty()){LinearLayout actions=new LinearLayout(a);Button copy=a.button("복사",false);copy.setOnClickListener(v->{((android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("누비 답변",m.optString("text")));a.toast("답변을 복사했어.");});actions.addView(copy);Button retry=a.button("요청 수정",false);retry.setOnClickListener(v->draft(previousUser(m.optString("id"))));actions.addView(retry);JSONArray log=m.optJSONArray("steps");if(log!=null&&log.length()>0){Button trace=a.button("실행 "+log.length()+"단계",false);trace.setOnClickListener(v->new AlertDialog.Builder(a).setTitle("Qwen 실행 기록").setMessage(GoalWorkspaceUi.stepText(log)).setPositiveButton("닫기",null).show());actions.addView(trace);}b.addView(actions);}
  row.addView(b,new LinearLayout.LayoutParams(-2,-2));messages.addView(row,Ui.match(a,-2,companionMode()?4:10));}

 String previousUser(String messageId){String text="";for(int n=0;n<history.length();n++){JSONObject m=history.optJSONObject(n);if(m==null)continue;if(messageId.equals(m.optString("id")))break;if(m.optString("role").equals("user"))text=m.optString("text");}return text;}
 void openDocument(JSONObject doc,JSONObject file){if(running||submitting){a.toast("작업이 끝난 뒤 문서를 열어줘.");return;}String name=file.optString("name");a.relay.document(doc.optString("job_id"),goalId,name,file.optString("sha256"),r->{if(r.has("error")){a.toast(r.optString("error"));return;}try{android.net.Uri u=android.net.Uri.parse(r.optString("uri"));companion.previewDocument(u,name);}catch(Exception e){a.toast("문서를 기기에 저장했어. DOCX/HWPX를 지원하는 앱이 필요해.");}});}
 JSONObject chatGptCompatibleFile(JSONObject doc,JSONObject file){if(file.optString("name").endsWith(".docx"))return file;JSONObject manifest=doc.optJSONObject("manifest");JSONArray files=manifest==null?null:manifest.optJSONArray("files");for(int n=0;files!=null&&n<files.length();n++){JSONObject candidate=files.optJSONObject(n);if(candidate!=null&&candidate.optString("name").equals("budget.docx"))return candidate;}return null;}
 void editDocumentWithChatGpt(JSONObject doc,JSONObject file){if(running||submitting){a.toast("작업이 끝난 뒤 문서를 열어줘.");return;}String name=file.optString("name");a.relay.document(doc.optString("job_id"),goalId,name,file.optString("sha256"),r->{if(r.has("error")){a.toast(r.optString("error"));return;}try{android.net.Uri u=android.net.Uri.parse(r.optString("uri"));Intent i=new Intent(a,BrowserWorkspaceActivity.class).setData(u).putExtra("start_url","https://chatgpt.com/");companion.route(i);}catch(Exception e){a.toast("ChatGPT를 열지 못했어.");}});}
 static String stateLabel(String s){return s.equals("completed")?"탐색 결과 · 출처 확인 가능":s.equals("cancelled")?"중지됨 · 입력 내용은 보관했어":s.equals("running")?"탐색 중":s.equals("failed")?"실행 실패 · 다시 요청할 수 있어":"";}
 void showSource(String url){if(running||submitting){a.toast("탐색을 중지한 뒤 원문을 열어줘.");return;}if(companion!=null)companion.browser();a.selectedUrl=url;a.web.loadUrl(url);address.setText("원문 · "+android.net.Uri.parse(url).getHost());}
 void busy(boolean value){running=value;if(companion!=null&&progress!=null)progress.setVisibility(value?View.VISIBLE:View.GONE);send.setText(value?"■":"↑");send.setContentDescription(value?"탐색 중지":"메시지 전송");}
 void submit(){pendingDocument=null;steps=new JSONArray();if(companion!=null)companion.refresh();String text=input.getText().toString().trim();if(text.isEmpty())return;campusTurn=java.util.regex.Pattern.compile("UNIST|유니스트|학사|장학|학교\\s*(공지|메일|포털)|수강|예비수강|COOP|인턴십|Outlook|아웃룩",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text).find();if(!a.relay.connected()){try{if(!a.relay.restore()){a.pair();return;}}catch(Exception e){a.pair();return;}}
  StringBuilder context=new StringBuilder();int from=Math.max(0,history.length()-4);for(int i=from;i<history.length();i++){JSONObject m=history.optJSONObject(i);if(m!=null){String v=m.optString("text");context.append(m.optString("role")).append(": ").append(v.substring(0,Math.min(v.length(),200))).append('\n');}}
  String task=context.length()==0?text:"이전 대화 (참고이며 새 관측 근거 아님):\n"+context+"현재 사용자 지시:\n"+text;if(task.length()>2000){a.toast("이전 대화를 포함해 너무 길어. 메시지를 조금 줄여줘.");return;}
  final int expected=++turnGeneration;requestId=UUID.randomUUID().toString();JSONObject m=message("user",text);turnId=m.optString("id");GoalStore.put(m,"state","running");history.put(m);save();render();submitting=true;busy(true);visible=true;progress.setText("요청을 Qwen에게 전달하고 있어…");((InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);input.clearFocus();
  JSONObject body=new JSONObject();GoalStore.put(body,"goal_id",goalId);GoalStore.put(body,"character",character);GoalStore.put(body,"task",task);GoalStore.put(body,"request_id",requestId);
  a.relay.chat("/chat-submit",body,r->{if(expected!=turnGeneration||!visible){if(!r.optString("job_id").isEmpty())a.relay.chat("/chat-cancel",new JSONObjectSafe("job_id",r.optString("job_id")),x->{});return;}submitting=false;if((r.has("error")&&!r.isNull("error"))||!goalId.equals(r.optString("goal_id"))){finishTurn("failed",r.optString("error","목표 연결을 확인해줘."),new JSONArray());return;}job=r.optString("job_id");input.setText("");save();pollErrors=0;receive(r);});
 }
 void receive(JSONObject r){if(!visible||!running)return;if(!goalId.equals(r.optString("goal_id"))||!job.equals(r.optString("job_id"))){finishTurn("failed","다른 목표의 응답은 표시하지 않았어.",new JSONArray());return;}
  JSONArray received=r.optJSONArray("progress");if(received!=null)steps=received;if(companion!=null)companion.refresh();String line=steps!=null&&steps.length()>0?steps.optString(steps.length()-1):"Qwen이 다음 행동을 고르고 있어…";progress.setText(line);String current=a.web.getUrl();if(current!=null&&current.startsWith("https://"))address.setText("브라우저 · "+android.net.Uri.parse(current).getHost());String state=r.optString("state");if(state.equals("completed")){if(r.optString("kind").equals("document")){pendingDocument=r.optJSONObject("document");if(pendingDocument!=null){GoalStore.put(pendingDocument,"job_id",job);JSONObject patch=new JSONObject();GoalStore.put(patch,"documentResult",pendingDocument);GoalStore.put(patch,"qwenSummary",r.optString("answer"));GoalStore.put(patch,"qwenSources",new JSONArray());a.store.patchGoal(goalId,patch);}}JSONArray cards=r.optJSONArray("items"),filtered=new JSONArray();JSONObject g=a.store.goal(goalId);JSONArray sources=g.optJSONArray("qwenSources");for(int i=0;cards!=null&&i<cards.length();i++){JSONObject c=cards.optJSONObject(i);boolean selected=false;for(int n=0;sources!=null&&n<sources.length();n++)if(sources.optString(n).equals(c.optString("url")))selected=true;if(selected)filtered.put(c);}finishTurn(state,r.optString("answer"),filtered);return;}if(state.equals("failed")||state.equals("cancelled")){finishTurn(state,r.optString("error","탐색을 중지했어."),new JSONArray());return;}ui.postDelayed(this::poll,1500);
 }
 void poll(){if(!visible||!running||job.isEmpty())return;final String expectedJob=job;final int expectedTurn=turnGeneration;a.relay.chat("/chat-status",new JSONObjectSafe("job_id",job),r->{if(!visible||!running||!expectedJob.equals(job)||expectedTurn!=turnGeneration)return;if((r.has("error")&&!r.isNull("error"))&&!r.has("state")){if(++pollErrors>=3){cancel();progress.setText("연결이 불안정해서 중지했어. 다시 요청해줘.");return;}ui.postDelayed(this::poll,2000);return;}pollErrors=0;receive(r);});}
 void finishTurn(String state,String text,JSONArray items){for(int i=0;i<history.length();i++){JSONObject m=history.optJSONObject(i);if(m!=null&&turnId.equals(m.optString("id")))GoalStore.put(m,"state",state);}JSONObject reply=message("assistant",text.replace("\\n","\n").replace("\\\"","\""));GoalStore.put(reply,"state",state);GoalStore.put(reply,"items",items);GoalStore.put(reply,"steps",steps);if(pendingDocument!=null){GoalStore.put(reply,"document",pendingDocument);pendingDocument=null;}history.put(reply);busy(false);submitting=false;job="";progress.setText(state.equals("completed")?"작업을 마쳤어. 답변의 결과와 확인할 사항을 봐줘.":"다시 요청할 수 있어.");save();render();if(companion!=null)companion.refresh();}
 void cancel(){turnGeneration++;String old=job;job="";ui.removeCallbacksAndMessages(null);if(!old.isEmpty())a.relay.chat("/chat-cancel",new JSONObjectSafe("job_id",old),r->{});if(running||submitting)finishTurn("cancelled","탐색을 중지했어. 원하면 조건을 바꿔 다시 부탁해줘.",new JSONArray());}
 void pause(){visible=false;if(!campusTurn||job.isEmpty())cancel();else ui.removeCallbacksAndMessages(null);save();}
 void resume(){visible=true;if(campusTurn&&running&&!job.isEmpty())poll();}
 static final class JSONObjectSafe extends JSONObject{JSONObjectSafe(String key,String value){GoalStore.put(this,key,value);}}
}
